VIDEO = {'footer': 'Session Management: Ids, Rotation, Timeouts and Sign-Out  ·  Security Basics  ·  Java', 'poster': {'headline': [('SESSION MANAGEMENT', 'text'), ('ROTATE, EXPIRE, END', 'accent')], 'taglines': [('A session id is a password that the server hands out', 'gold')], 'before': {'code': 'SESSIONID=same-id-forever', 'note': 'planted, copied, never ends', 'tag': 'BEFORE'}, 'after': {'code': '__Host-session; Secure; HttpOnly', 'note': 'new at sign-in, ended on the server', 'tag': 'AFTER'}}, 'highlight': {'console_green': ['AFTER ENCODING', 'AFTER SIGN-IN, A BANK THAT ISSUES', 'AFTER STEP-UP', 'THE SIGN-IN RESPONSE', 'THE SIGN-OUT RESPONSE', 'A COPY MADE BEFORE', 'THE ANSWER FROM B, BOTH'], 'console_rose': ['AFTER SIGN-IN, A BANK THAT KEEPS', 'A BANK WHOSE SIGN-OUT', 'A WEAK COOKIE', 'ITS PROBLEMS', 'THE ANSWER FROM B, EACH'], 'console_amber': ['BEFORE ENCODING', 'BEFORE ANA SIGNS IN', 'THE REQUEST', 'THE ANSWER:', 'THE ANSWERS:', 'HOW BASE64URL', 'IDLE', 'ABSOLUTE', 'PAYMENTS', 'HOW LONG', 'A WRONG PASSWORD'], 'console_cyan': ['WHAT THE STORE KEEPS', 'THE REAL IDS', 'THE SETTINGS', 'THE ACCOUNT PAGE', 'ANA IS SIGNED IN']}}
